package com.fixmer.mared;
import com.fixmer.genesis.technology.workspace.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import static com.fixmer.genesis.technology.workspace.WorkspaceWire112.*;
/** Real child JVM and forced termination. Does not simulate Minecraft readiness. */
public final class WorkspaceProcessChecks112 {
 private static final UUID OWNER=UUID.fromString("10000000-0000-0000-0000-000000000001"),CREATE=UUID.fromString("20000000-0000-0000-0000-000000000001");private static int checks;private static void ok(boolean v){checks++;if(!v)throw new AssertionError("process112 "+checks);}
 private static Request q(String op,String path,String file,String text,long revision,long projectRevision){return new Request(UUID.randomUUID(),op,CREATE.toString(),path,file,text,revision,projectRevision,"","","");}
 private static Map<String,String> view(WorkspaceStore112 s)throws Exception{return s.execute(OWNER,true,q("VIEW","","","",0,0));}private static Map<String,String> read(WorkspaceStore112 s)throws Exception{return s.execute(OWNER,true,q("READ","state.txt","","",0,0));}
 private static void child(Path root)throws Exception{try(var s=new WorkspaceStore112(root)){s.execute(OWNER,true,new Request(CREATE,"CREATE","","","","Crash checks",0,0,"","",""));if(view(s).get("files").isEmpty())s.execute(OWNER,true,q("NEW","state.txt","","0\n"+"0".repeat(12000),0,Long.parseLong(view(s).get("projectRevision"))));for(int i=1;i<10000;i++){var old=read(s);s.execute(OWNER,true,q("SAVE","state.txt",old.get("file"),i+"\n"+Integer.toString(i).repeat(1000),Long.parseLong(old.get("revision")),0));Files.writeString(root.resolve("writer-ready"),Integer.toString(i));}}}
 private static void rejectDuplicate(Path root)throws Exception{
  try(var duplicate=new WorkspaceStore112(root)){throw new AssertionError("lock missing");}
  catch(java.io.IOException expected){ok(expected.getMessage().equals("LOCKED"));}
 }
 public static void main(String[] args)throws Exception{if(args.length==2&&args[0].equals("probe")){rejectDuplicate(Path.of(args[1]));return;}if(args.length==2&&args[0].equals("writer")){child(Path.of(args[1]));return;}Path root=Files.createTempDirectory("Genesis process112 ");String java=Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"java.exe":"java").toString();Process writer=new ProcessBuilder(java,"-cp",System.getProperty("java.class.path"),WorkspaceProcessChecks112.class.getName(),"writer",root.toString()).redirectErrorStream(true).redirectOutput(root.resolve("child.log").toFile()).start();try{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(!Files.exists(root.resolve("writer-ready"))&&writer.isAlive()&&System.nanoTime()<end)Thread.sleep(5);ok(Files.exists(root.resolve("writer-ready")));ok(writer.isAlive());try{try(var duplicate=new WorkspaceStore112(root)){}throw new AssertionError("cross-JVM lock missing");}catch(java.io.IOException expected){ok(expected.getMessage().equals("LOCKED"));}writer.destroyForcibly();ok(writer.waitFor(10,TimeUnit.SECONDS));Files.writeString(root.resolve(".workspace112-interrupted.tmp"),"incomplete");try(var s=new WorkspaceStore112(root)){
  rejectDuplicate(root);
  Process probe=new ProcessBuilder(java,"-cp",System.getProperty("java.class.path"),WorkspaceProcessChecks112.class.getName(),"probe",root.toString()).inheritIO().start();
  try{ok(probe.waitFor(10,TimeUnit.SECONDS)&&probe.exitValue()==0);}finally{if(probe.isAlive())probe.destroyForcibly();}
  var d=read(s);String text=d.get("text");int newline=text.indexOf('\n');ok(newline>0);String number=text.substring(0,newline);ok(Integer.parseInt(number)>0);ok(text.substring(newline+1).equals(number.repeat(1000)));ok(!Files.exists(root.resolve(".workspace112-interrupted.tmp")));s.execute(OWNER,true,q("SAVE","state.txt",d.get("file"),"after-crash",Long.parseLong(d.get("revision")),0));ok(read(s).get("text").equals("after-crash"));}try(var s=new WorkspaceStore112(root)){ok(read(s).get("text").equals("after-crash"));}}finally{if(writer.isAlive()){writer.destroyForcibly();writer.waitFor(10,TimeUnit.SECONDS);}try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}System.out.println("Workspace112 actual child-JVM lock/forced-kill/whole-snapshot/reopen checks passed: "+checks+"; no Minecraft runtime.");}
}
